	/**  Kökten bu döneme burçlar: `[dasha]`, `[dasha, alt dönem]`, … */
	signs: Sign[],
	/**  1..=3; `signs.len()` ile aynı. */
	level: number,
	/**  1 ya da 2: dönemin ait olduğu çevrim. */
	cycle: number,
	start_jd_ut: number | null,
	end_jd_ut: number | null,
	/**  Alt dönemleri istenebilir (`level < MAX_SIGN_DASHA_LEVEL`). */
